import{_ as a,o as t,c as s,a2 as o}from"./chunks/framework.Dg5fKO7V.js";const f=JSON.parse('{"title":"Downloads and Offline","description":"","frontmatter":{},"headers":[],"relativePath":"Downloads-And-Offline.md","filePath":"Downloads-And-Offline.md","lastUpdated":1788563284000}'),n={name:"Downloads-And-Offline.md"};function i(r,e,h,l,d,p){return t(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="downloads-and-offline" tabindex="-1">Downloads and Offline <a class="header-anchor" href="#downloads-and-offline" aria-label="Permalink to &quot;Downloads and Offline&quot;">​</a></h1><p>Saving a title takes its page with it: the description, the characters, the artwork, the episode titles and thumbnails, and the franchise it belongs to, all fetched before the snapshot is written rather than assumed to be there. A saved episode then plays from the disk whether there is a connection or not, and is found under the track it was saved as rather than only the one being watched.</p><h2 id="where-things-go" tabindex="-1">Where things go <a class="header-anchor" href="#where-things-go" aria-label="Permalink to &quot;Where things go&quot;">​</a></h2><p>Two locations, on purpose.</p><p><strong>Media</strong> goes where you chose, under <code>&lt;your folder&gt;/&lt;language&gt;/&lt;anime&gt;/</code>. It is yours, readable by any player, and untouched by uninstalling the app.</p><p><strong>Everything else</strong> stays in the application data directory: the queue, progress, and the offline snapshot. See <a href="./Data-Privacy-And-Security">Data, Privacy and Security</a>.</p><h2 id="the-pipeline" tabindex="-1">The pipeline <a class="header-anchor" href="#the-pipeline" aria-label="Permalink to &quot;The pipeline&quot;">​</a></h2><p><code>src-tauri/src/downloads/</code>:</p><ol><li><strong><code>queue.rs</code></strong> schedules. Several episodes can be requested at once, and the queue bounds how many transfer at a time so downloading does not starve playback.</li><li><strong><code>transfer/</code></strong> moves bytes. A direct file is a ranged fetch. HLS is different: fetch the playlist, fetch every segment, decrypt AES-128 where the playlist says to, then assemble.</li><li><strong><code>ffmpeg.rs</code></strong> assembles segments into one playable file.</li><li><strong><code>offline/</code></strong> writes the snapshot.</li><li><strong><code>paths.rs</code></strong> owns naming and layout, so the same episode always lands in the same place.</li></ol><p>Progress is reported per episode as an event, which is what the offline page draws.</p><h2 id="the-snapshot" tabindex="-1">The snapshot <a class="header-anchor" href="#the-snapshot" aria-label="Permalink to &quot;The snapshot&quot;">​</a></h2><p>A downloaded episode without its metadata is a file with a cryptic name. The snapshot is what makes the library still work offline: the title, the description, the cover and the episode titles, written beside the media when the download completes.</p><p>That is why the offline page shows real cards rather than filenames, and why it survives a cache clear. Reopening the offline page restores those caches from the snapshots.</p><h2 id="reconciliation" tabindex="-1">Reconciliation <a class="header-anchor" href="#reconciliation" aria-label="Permalink to &quot;Reconciliation&quot;">​</a></h2><p>Files disappear. Users move folders, delete episodes, or restore from a backup. On opening the offline page the app reconciles: rows whose file is gone are dropped, and files it finds again are picked back up.</p><p>This is also why the download directory can be changed without losing what you already have.</p><h2 id="failures" tabindex="-1">Failures <a class="header-anchor" href="#failures" aria-label="Permalink to &quot;Failures&quot;">​</a></h2><p>A failed download stays visible with a retry rather than vanishing, because the usual causes are temporary: the source went down, the network dropped, the disk filled. Retrying resumes rather than starting over where the source supports ranges.</p><h2 id="things-worth-knowing" tabindex="-1">Things worth knowing <a class="header-anchor" href="#things-worth-knowing" aria-label="Permalink to &quot;Things worth knowing&quot;">​</a></h2><ul><li><strong>HLS downloads are many small requests</strong>, not one big one. A show with long episodes is hundreds of segments, and a single failed segment fails the episode rather than producing a broken file.</li><li><strong>Assembly needs ffmpeg</strong>, which ships with the app.</li><li><strong>A partial or empty assembly is never trusted.</strong> It is treated as a failure, because handing the player a truncated file is worse than reporting the download did not work.</li></ul>',20)])])}const g=a(n,[["render",i]]);export{f as __pageData,g as default};
